package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var (
	reader *bufio.Reader
	writer *bufio.Writer
)

func readToken() string {
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			break
		}
		fields := strings.Fields(line)
		if len(fields) > 0 {
			return fields[0]
		}
	}
	return ""
}

func readInt() int {
	token := readToken()
	n, _ := strconv.Atoi(token)
	return n
}

func solve() {
	n := readInt()
	m := readInt()

	if m == 1 {
		writer.WriteString(strconv.Itoa(n - 1))
	} else {
		writer.WriteString(strconv.FormatInt(int64(n)*int64(m-1), 10))
	}
}

func main() {
	reader = bufio.NewReader(os.Stdin)
	writer = bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	solve()
}
