	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	tokens := make([]string, 0)
	readToken := func() string {
		for len(tokens) == 0 {
			line, _ := reader.ReadString('\n')
			parts := strings.Fields(line)
			tokens = append(tokens, parts...)
		}
		tok := tokens[0]
		tokens = tokens[1:]
		return tok
	}

	readInt := func() int {
		v, _ := strconv.Atoi(readToken())
		return v
	}

	n := readInt()
	m := readInt()

	if m == 1 {
		fmt.Fprintln(writer, n-1)
	} else {
		fmt.Fprintln(writer, int64(n)*int64(m-1))
